"use client";

import * as React from "react";
import type { IconDefinition } from "@/lib/icons/schema";
import type { PXIconDefinition } from "@pxui/core";

export type IconPathItem = {
  d: string;
  fillRule?: "nonzero" | "evenodd" | "inherit";
  clipRule?: "nonzero" | "evenodd" | "inherit";
};

export interface PixelIconBaseProps extends Omit<React.SVGProps<SVGSVGElement>, "ref"> {
  definition: IconDefinition | PXIconDefinition;
  size?: number | string;
  color?: string;
  strokeWidth?: number | string;
  filled?: boolean;
  animated?: boolean;
  animation?: {
    cssClass?: string;
    frames?: readonly { durationMs: number; transform?: string; opacity?: number }[];
  };
  duration?: number;
  delay?: number;
  loop?: boolean;
  trigger?: "auto" | "hover" | "click";
  title?: string;
  "aria-label"?: string;
}

export const PixelIconBase = React.forwardRef<SVGSVGElement, PixelIconBaseProps>(
  (
    {
      definition,
      size = 24,
      color = "currentColor",
      strokeWidth,
      filled = false,
      animated = false,
      animation,
      duration,
      delay,
      loop = true,
      trigger = "auto",
      className = "",
      title,
      "aria-label": ariaLabel,
      style,
      ...restProps
    },
    ref
  ) => {
    // Resolve width/height from number or string (e.g. 24, "24px", "1.5rem")
    const dimension = typeof size === "number" ? `${size}px` : size;

    const def = definition as unknown as {
      geometry?: { paths?: readonly IconPathItem[]; filled?: readonly IconPathItem[] };
      paths?: readonly IconPathItem[];
      filled?: readonly IconPathItem[];
      animation?: { cssClass?: string };
    };

    const rawPaths: readonly IconPathItem[] = def.geometry?.paths || def.paths || [];
    const rawFilled: readonly IconPathItem[] | undefined = def.geometry?.filled || def.filled;
    const paths: readonly IconPathItem[] =
      filled && rawFilled && rawFilled.length > 0 ? rawFilled : rawPaths;

    const activeAnimation = animation || def.animation;
    const hasAnimation = animated && Boolean(activeAnimation);
    const animationClass = hasAnimation ? activeAnimation?.cssClass || "" : "";

    const isMeaningful = Boolean(ariaLabel || title);

    const animationStyle: React.CSSProperties = {};
    if (hasAnimation) {
      if (duration !== undefined) {
        animationStyle.animationDuration = `${duration}ms`;
      }
      if (delay !== undefined) {
        animationStyle.animationDelay = `${delay}ms`;
      }
      if (loop === false) {
        animationStyle.animationIterationCount = "1";
      }
    }

    return (
      <svg
        ref={ref}
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 24 24"
        width={dimension}
        height={dimension}
        fill={color}
        strokeWidth={strokeWidth}
        data-trigger={trigger !== "auto" ? trigger : undefined}
        className={`pixel-crisp inline-block shrink-0 select-none ${animationClass} ${className}`.trim()}
        role={isMeaningful ? "img" : undefined}
        aria-hidden={isMeaningful ? undefined : true}
        aria-label={ariaLabel}
        style={{
          color,
          shapeRendering: "crispEdges",
          ...animationStyle,
          ...style,
        }}
        {...restProps}
      >
        {title ? <title>{title}</title> : null}
        {paths.map((p, idx) => (
          <path
            key={idx}
            d={p.d}
            fillRule={p.fillRule}
            clipRule={p.clipRule}
          />
        ))}
      </svg>
    );
  }
);

PixelIconBase.displayName = "PixelIconBase";

// Backward-compatibility exports
export const PXIconBase = PixelIconBase;
export type PXIconBaseProps = PixelIconBaseProps;

export type IconCategory =
  | "Actions & Controls"
  | "Arrows & Navigation"
  | "Files & Folders"
  | "Communication"
  | "People & Social"
  | "Devices & Hardware"
  | "Development & Code"
  | "Business & Finance"
  | "Commerce"
  | "Media & Creative"
  | "Maps & Travel"
  | "Buildings & Objects"
  | "Health & Fitness"
  | "Weather & Nature"
  | "Security & Privacy"
  | "Time & Calendar"
  | "Education"
  | "AI & Emerging Tech"
  | "Brands & Technology"
  | "Miscellaneous & Symbols";

export type AnimationFamily =
  | "state"
  | "directional"
  | "attention"
  | "reveal"
  | "signal"
  | "loop";

export type AnimationType =
  | "spin"
  | "pulse"
  | "bounce"
  | "wiggle"
  | "blink"
  | "ring"
  | "shake"
  | "beat";

export type AnimationName =
  | "spin"
  | "pulse"
  | "bounce"
  | "wiggle"
  | "blink"
  | "ring"
  | "shake"
  | "beat"
  | "open"
  | "close"
  | "check"
  | "error"
  | "success"
  | "download"
  | "upload"
  | "appear"
  | "disappear"
  | "loading"
  | string;

export interface AnimationDefinition {
  family: AnimationFamily;
  type: AnimationType;
  cssClass: string;
  description: string;
  duration?: number;
  trigger?: "auto" | "hover" | "click" | "focus" | "controlled" | "always" | "mount";
}

export interface BrandDefinition {
  brand: string;
  owner: string;
  source?: string;
  guidelinesUrl?: string;
}

export interface IconPathDefinition {
  d: string;
  fillRule?: "nonzero" | "evenodd";
  clipRule?: "nonzero" | "evenodd";
}

export interface IconDefinition {
  name: string; // lowercase-kebab-case, e.g. "home", "search"
  componentName?: string; // Public framework component name, e.g. "PXIconHome"
  slug?: string; // Registry, URL and artifact identifier, e.g. "px-home"
  title: string;
  description?: string;
  category: IconCategory;
  family?: string; // Related geometric/semantic family (Section 7.19)
  tags: string[];
  aliases?: string[];
  grid: 24;
  paths: IconPathDefinition[];
  geometry?: {
    grid: number;
    paths: IconPathDefinition[];
    bounds?: {
      minX: number;
      minY: number;
      maxX: number;
      maxY: number;
    };
  };
  filled?: IconPathDefinition[];
  variants?: string[]; // Supported canonical variants, e.g. ["outline", "filled"]
  animation?: AnimationDefinition;
  brand?: BrandDefinition;
  platforms?: string[]; // Supported generated targets (Section 7.27)
  status?: "draft" | "experimental" | "stable" | "deprecated"; // Lifecycle state (Section 7.28)
  introduced?: string; // First PXUI release containing icon (Section 7.29)
  introducedVersion: string;
  deprecated?: boolean; // Deprecation state (Section 7.30)
  replacedBy?: string; // Migration target when deprecated
}

/**
 * PixelIconProps conforming strictly to Section 3.11.1 of the design system specification.
 */
export interface PixelIconProps extends React.SVGProps<SVGSVGElement> {
  size?: number | string;
  color?: string;
  strokeWidth?: number;
  animated?: boolean;
  animation?: AnimationName;
  duration?: number;
  delay?: number;
  loop?: boolean;
  trigger?: "auto" | "hover" | "click" | "focus" | "controlled";
  filled?: boolean;
  title?: string;
  className?: string;
  "aria-label"?: string;
}

/**
 * Backward compatibility alias for PXIconProps
 */
export type PXIconProps = PixelIconProps;

